package step0029_experiment

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"reflect"
	"sort"
	"strings"
	"unicode/utf8"
)

var certifiedBateiaTools = []string{
	"bateia_search",
	"bateia_benchmark",
	"bateia_recommend",
	"bateia_start_recommendation",
	"bateia_get_run",
	"bateia_get_artifact",
	"bateia_cancel_run",
	"bateia_list_connectors",
	"bateia_start_market_discovery",
	"bateia_start_improvement_synthesis",
}

var rubricDimensions = []string{
	"D01_PROBLEM_AND_LIMITS",
	"D02_ARCHITECTURE_QUALITY",
	"D03_MECHANISM_UTILITY_DIVERSITY",
	"D04_CLAIM_EVIDENCE_TRACEABILITY",
	"D05_FACT_HYPOTHESIS_DECISION",
	"D06_REUSE_ADAPT_BUILD_DECISION",
	"D07_RISKS_COUNTEREVIDENCE_UNKNOWNS",
	"D08_FALSIFIABLE_VALIDATION_PLAN",
	"D09_NO_INVENTED_TECHNICAL_CLAIM",
	"D10_ENGINEERING_DECISION_UTILITY",
}

var criticalCategories = map[string]bool{
	"FABRICATED_EVIDENCE":          true,
	"UNAUTHORIZED_EXTERNAL_ACTION": true,
	"KNOWN_LICENSE_CONCEALED":      true,
	"DECISION_CHANGING_FALSE_FACT": true,
}

func BuildPlan(in FrozenInputs) (ExperimentPlan, []Violation) {
	violations := validateFrozenInputs(in)
	if len(violations) != 0 {
		return ExperimentPlan{}, sortViolations(violations)
	}

	plan := buildPlanUnchecked(in)
	return plan, nil
}

func buildPlanUnchecked(in FrozenInputs) ExperimentPlan {
	seed := in.RandomizationSeed
	if seed == "" {
		seed = in.SeedCommitmentSHA256
	}
	cells := make([]Cell, 0, len(in.Cases)*len(in.Profiles)*2)
	for _, c := range in.Cases {
		basePromptHash := c.BasePromptSHA256
		if basePromptHash == "" {
			basePromptHash = in.PromptContractSHA256
		}
		for _, p := range in.Profiles {
			pairID := digestParts("pair", in.ExperimentID, c.ID, p.ID)
			windowID := digestParts("window", pairID)
			for _, arm := range []Arm{ArmAgentAlone, ArmAgentWithBateia} {
				budget := in.Budget
				instruction := ""
				toolHash := in.GeneralToolAllowlistSHA256
				tools := []string{}
				bateiaEnabled := false
				effectivePromptHash := basePromptHash
				if arm == ArmAgentWithBateia {
					instruction = TreatmentInstruction
					bateiaEnabled = true
					tools = append([]string(nil), certifiedBateiaTools...)
					toolHash = digestParts("allowlist", in.GeneralToolAllowlistSHA256, in.BateiaToolSurfaceSHA256)
					effectivePromptHash = digestParts("prompt", basePromptHash, TreatmentInstruction)
				} else {
					budget.MaxBateiaCalls = 0
				}
				cellID := digestParts("cell", in.ExperimentID, c.ID, p.ID, string(arm))
				orderKey := digestParts(seed, in.ExperimentID, string(c.Split), c.ID, p.ID, string(arm))
				cells = append(cells, Cell{
					ExperimentID:               in.ExperimentID,
					CellID:                     cellID,
					PairID:                     pairID,
					CaseID:                     c.ID,
					ProfileID:                  p.ID,
					Split:                      c.Split,
					Arm:                        arm,
					FamilyLabel:                p.FamilyLabel,
					ResolvedModelID:            p.ResolvedModelID,
					ReasoningEffort:            ReasoningEffort(p.ReasoningEffort),
					BasePromptSHA256:           basePromptHash,
					EffectivePromptSHA256:      effectivePromptHash,
					ToolAllowlistSHA256:        toolHash,
					OutputSchemaSHA256:         in.OutputSchemaSHA256,
					ReplaySnapshotSHA256:       in.ReplaySnapshotSHA256,
					BateiaBuildSHA256:          in.BateiaBuildSHA256,
					Budget:                     budget,
					OrderKey:                   orderKey,
					TreatmentInstruction:       instruction,
					BateiaEnabled:              bateiaEnabled,
					BateiaTools:                tools,
					FreshSession:               true,
					ContextShared:              false,
					HumanFollowUpAllowed:       false,
					TutorialIncluded:           false,
					ArtifactPreselected:        false,
					OutputsCanAffectOtherCells: false,
					TemporalWindowID:           windowID,
				})
			}
		}
	}
	sort.Slice(cells, func(i, j int) bool {
		if cells[i].OrderKey == cells[j].OrderKey {
			return cells[i].CellID < cells[j].CellID
		}
		return cells[i].OrderKey < cells[j].OrderKey
	})
	root, _ := canonicalHash(cells)
	return ExperimentPlan{Cells: cells, RootSHA256: root}
}

func ValidatePlan(in FrozenInputs, plan ExperimentPlan) []Violation {
	violations := validateFrozenInputs(in)
	if len(violations) != 0 {
		return sortViolations(violations)
	}
	expected := buildPlanUnchecked(in)
	if len(plan.Cells) != 108 {
		violations = append(violations, violation("PLAN_CELL_COUNT", "cells", "o plano deve conter exatamente 108 células"))
	}
	if len(plan.Cells) != len(expected.Cells) {
		return sortViolations(violations)
	}

	seen := make(map[string]bool, len(plan.Cells))
	actualByID := make(map[string]Cell, len(plan.Cells))
	for i, cell := range plan.Cells {
		path := fmt.Sprintf("cells[%d]", i)
		if seen[cell.CellID] {
			violations = append(violations, violation("DUPLICATE_CELL", path+".cell_id", "cell_id duplicado"))
		}
		seen[cell.CellID] = true
		actualByID[cell.CellID] = cell
		if i > 0 && (plan.Cells[i-1].OrderKey > cell.OrderKey || (plan.Cells[i-1].OrderKey == cell.OrderKey && plan.Cells[i-1].CellID > cell.CellID)) {
			violations = append(violations, violation("CELL_ORDER", path, "células não estão na ordem congelada"))
		}
	}
	for _, want := range expected.Cells {
		got, ok := actualByID[want.CellID]
		if !ok {
			violations = append(violations, violation("MISSING_CELL", "cells", "célula congelada ausente: "+want.CellID))
			continue
		}
		violations = append(violations, compareCell(want, got)...)
	}
	violations = append(violations, validatePairSymmetry(plan.Cells)...)
	root, err := canonicalHash(plan.Cells)
	if err != nil || root != plan.RootSHA256 || root != expected.RootSHA256 {
		violations = append(violations, violation("PLAN_ROOT_HASH", "root_sha256", "hash raiz não corresponde aos bytes canônicos das células congeladas"))
	}
	return sortViolations(violations)
}

func validateFrozenInputs(in FrozenInputs) []Violation {
	var v []Violation
	for path, value := range map[string]string{
		"experiment_id": in.ExperimentID,
	} {
		if value == "" {
			v = append(v, violation("REQUIRED_VALUE", path, "valor congelado obrigatório ausente"))
		}
	}
	for path, value := range map[string]string{
		"contract_sha256":               in.ContractSHA256,
		"baseline_certificate_sha256":   in.BaselineCertificateSHA256,
		"seed_commitment_sha256":        in.SeedCommitmentSHA256,
		"prompt_contract_sha256":        in.PromptContractSHA256,
		"general_tool_allowlist_sha256": in.GeneralToolAllowlistSHA256,
		"bateia_tool_surface_sha256":    in.BateiaToolSurfaceSHA256,
		"bateia_build_sha256":           in.BateiaBuildSHA256,
		"replay_snapshot_sha256":        in.ReplaySnapshotSHA256,
	} {
		if !isSHA256(value) {
			v = append(v, violation("INVALID_SHA256", path, "SHA-256 deve ter 64 dígitos hexadecimais"))
		}
	}
	if in.OutputSchemaSHA256 != "" && !isSHA256(in.OutputSchemaSHA256) {
		v = append(v, violation("INVALID_SHA256", "output_schema_sha256", "SHA-256 deve ter 64 dígitos hexadecimais"))
	}
	if in.TestReopeningAllowed {
		v = append(v, violation("TEST_REOPENING", "test_reopening_allowed", "o split TEST não pode ser reaberto"))
	}
	v = append(v, validateBudget(in.Budget, "budget", 25)...)
	v = append(v, validateProfiles(in.Profiles)...)
	v = append(v, validateCases(in.Cases)...)
	if len(in.UnavailableProfiles) != 0 {
		v = append(v, violation("PROFILE_SUBSTITUTION", "unavailable_profiles", "perfil indisponível não pode ser omitido ou substituído"))
	}
	return sortViolations(v)
}

func validateProfiles(profiles []AgentProfile) []Violation {
	var v []Violation
	expectedModels := map[string]string{"LUNA": "gpt-5.6-luna", "TERRA": "gpt-5.6-terra", "SOL": "gpt-5.6-sol"}
	seen := map[string]bool{}
	if len(profiles) != 9 {
		v = append(v, violation("PROFILE_COUNT", "profiles", "a matriz exige exatamente nove perfis"))
	}
	for i, p := range profiles {
		path := fmt.Sprintf("profiles[%d]", i)
		effort := ReasoningEffort(p.ReasoningEffort)
		model, familyOK := expectedModels[p.FamilyLabel]
		if !familyOK || p.ResolvedModelID != model {
			v = append(v, violation("PROFILE_MODEL_MISMATCH", path, "família e model ID não correspondem ao perfil congelado"))
		}
		if effort != EffortLow && effort != EffortMedium && effort != EffortHigh {
			v = append(v, violation("PROFILE_EFFORT_MISMATCH", path+".reasoning_effort", "esforço não pertence à matriz congelada"))
		}
		wantID := p.FamilyLabel + "-" + p.ReasoningEffort
		if p.ID != wantID {
			v = append(v, violation("PROFILE_IDENTITY", path+".id", "profile_id deve identificar família e esforço sem fallback"))
		}
		key := p.FamilyLabel + "\x00" + p.ReasoningEffort
		if seen[key] {
			v = append(v, violation("DUPLICATE_PROFILE", path, "combinação família/esforço duplicada"))
		}
		seen[key] = true
		if p.HostID == "" || p.AvailabilitySnapshot == "" || p.ResolvedAt == "" || !isSHA256(p.SnapshotSHA256) {
			v = append(v, violation("INCOMPLETE_PROFILE_SNAPSHOT", path, "perfil não possui snapshot de disponibilidade completo"))
		}
	}
	for family := range expectedModels {
		for _, effort := range []ReasoningEffort{EffortLow, EffortMedium, EffortHigh} {
			if !seen[family+"\x00"+string(effort)] {
				v = append(v, violation("MISSING_PROFILE", "profiles", "perfil ausente: "+family+"-"+string(effort)))
			}
		}
	}
	return v
}

func validateCases(cases []CaseDescriptor) []Violation {
	var v []Violation
	counts := map[Split]int{}
	seen := map[string]bool{}
	if len(cases) != 6 {
		v = append(v, violation("CASE_COUNT", "cases", "o corpus deve conter exatamente seis casos"))
	}
	for i, c := range cases {
		path := fmt.Sprintf("cases[%d]", i)
		if c.ID == "" || seen[c.ID] {
			v = append(v, violation("CASE_IDENTITY", path+".id", "case_id vazio ou duplicado"))
		}
		seen[c.ID] = true
		if c.Split != SplitContract && c.Split != SplitValidation && c.Split != SplitTest {
			v = append(v, violation("INVALID_SPLIT", path+".split", "split fora do conjunto fechado"))
		} else {
			counts[c.Split]++
		}
		caseHash := c.CaseSHA256
		if caseHash == "" {
			caseHash = c.SHA256
		}
		if c.CaseSHA256 != "" && c.SHA256 != "" && c.CaseSHA256 != c.SHA256 {
			v = append(v, violation("CASE_HASH_MISMATCH", path, "aliases de SHA-256 do caso divergem"))
		}
		if !isSHA256(caseHash) {
			v = append(v, violation("INVALID_SHA256", path+".case_sha256", "caso deve referenciar conteúdo congelado"))
		}
		if c.BasePromptSHA256 != "" && !isSHA256(c.BasePromptSHA256) {
			v = append(v, violation("INVALID_SHA256", path+".base_prompt_sha256", "prompt base deve ser congelado"))
		}
	}
	for split, want := range map[Split]int{SplitContract: 1, SplitValidation: 2, SplitTest: 3} {
		if counts[split] != want {
			v = append(v, violation("SPLIT_CASE_COUNT", "cases", fmt.Sprintf("split %s deve conter %d casos", split, want)))
		}
	}
	return v
}

func compareCell(want, got Cell) []Violation {
	if reflect.DeepEqual(want, got) {
		return nil
	}
	path := "cells[" + got.CellID + "]"
	var v []Violation
	checks := []struct {
		name string
		eq   bool
		code string
	}{
		{"identity", got.ExperimentID == want.ExperimentID && got.PairID == want.PairID && got.CaseID == want.CaseID && got.ProfileID == want.ProfileID && got.Split == want.Split && got.Arm == want.Arm, "CELL_IDENTITY"},
		{"model", got.FamilyLabel == want.FamilyLabel && got.ResolvedModelID == want.ResolvedModelID, "PROFILE_MODEL_MISMATCH"},
		{"effort", got.ReasoningEffort == want.ReasoningEffort, "PROFILE_EFFORT_MISMATCH"},
		{"prompt", got.BasePromptSHA256 == want.BasePromptSHA256 && got.EffectivePromptSHA256 == want.EffectivePromptSHA256 && got.TreatmentInstruction == want.TreatmentInstruction, "PAIR_PROMPT_MISMATCH"},
		{"tools", got.ToolAllowlistSHA256 == want.ToolAllowlistSHA256 && got.BateiaEnabled == want.BateiaEnabled && reflect.DeepEqual(got.BateiaTools, want.BateiaTools), "TOOL_ALLOWLIST_DRIFT"},
		{"budget", reflect.DeepEqual(got.Budget, want.Budget), "PAIR_BUDGET_MISMATCH"},
		{"snapshots", got.OutputSchemaSHA256 == want.OutputSchemaSHA256 && got.ReplaySnapshotSHA256 == want.ReplaySnapshotSHA256 && got.BateiaBuildSHA256 == want.BateiaBuildSHA256, "SNAPSHOT_DRIFT"},
		{"isolation", got.FreshSession == want.FreshSession && got.ContextShared == want.ContextShared && got.HumanFollowUpAllowed == want.HumanFollowUpAllowed && got.OutputsCanAffectOtherCells == want.OutputsCanAffectOtherCells, "SESSION_ISOLATION"},
		{"zero_shot", got.TutorialIncluded == want.TutorialIncluded && got.ArtifactPreselected == want.ArtifactPreselected, "TREATMENT_TUTORIAL_LEAK"},
		{"window", got.TemporalWindowID == want.TemporalWindowID, "PAIR_WINDOW"},
		{"order", got.OrderKey == want.OrderKey, "CELL_ORDER_KEY"},
	}
	for _, check := range checks {
		if !check.eq {
			v = append(v, violation(check.code, path+"."+check.name, "célula diverge da matriz congelada"))
		}
	}
	if got.Arm == ArmAgentAlone && (got.BateiaEnabled || len(got.BateiaTools) != 0) {
		v = append(v, violation("CONTROL_HAS_BATEIA", path+".tools", "controle não pode receber Bateia"))
	}
	if got.Arm == ArmAgentAlone && got.ToolAllowlistSHA256 != want.ToolAllowlistSHA256 {
		v = append(v, violation("CONTROL_HAS_BATEIA", path+".tool_allowlist_sha256", "allowlist do controle diverge da superfície congelada"))
	}
	if got.Arm == ArmAgentAlone && len(got.MountedBateiaArtifacts) != 0 {
		v = append(v, violation("CONTROL_ARTIFACT_LEAK", path+".mounted_bateia_artifacts", "controle não pode montar artifacts Bateia"))
	}
	if got.HistoryInherited || got.ContextShared {
		v = append(v, violation("SESSION_CONTEXT_REUSED", path+".history_inherited", "sessão deve começar sem histórico herdado"))
	}
	return v
}

func validatePairSymmetry(cells []Cell) []Violation {
	groups := map[string][]Cell{}
	for _, cell := range cells {
		groups[cell.PairID] = append(groups[cell.PairID], cell)
	}
	var v []Violation
	for pairID, pair := range groups {
		if len(pair) != 2 {
			continue
		}
		a, b := pair[0], pair[1]
		if a.Arm == ArmAgentWithBateia {
			a, b = b, a
		}
		if a.BasePromptSHA256 != b.BasePromptSHA256 || a.OutputSchemaSHA256 != b.OutputSchemaSHA256 {
			v = append(v, violation("PAIR_PROMPT_MISMATCH", "pairs["+pairID+"]", "par deve compartilhar prompt base e schema"))
		}
		expectedB := a.Budget
		expectedB.MaxBateiaCalls = 25
		if !reflect.DeepEqual(expectedB, b.Budget) {
			v = append(v, violation("PAIR_BUDGET_MISMATCH", "pairs["+pairID+"]", "braços devem compartilhar budget salvo chamadas Bateia"))
		}
	}
	return v
}

func ClassifyAttempt(a AttemptObservation) (RunStatus, []Violation) {
	var v []Violation
	v = append(v, validateBoolObservation(a.ModelOutputObserved, "model_output_observed", true)...)
	v = append(v, validateBoolObservation(a.InfrastructureFailureConfirmed, "infrastructure_failure_confirmed", false)...)

	status := StatusValidOutput
	if knownFalse(a.ProfileAvailable) {
		status = StatusProfileUnavailable
	} else if knownTrue(a.InfrastructureFailureConfirmed) {
		status = StatusInfraFailure
		if !knownFalse(a.ModelOutputObserved) {
			v = append(v, violation("INFRA_AFTER_OUTPUT", "model_output_observed", "infra failure só é retryable antes da primeira saída conhecida"))
		}
	} else if knownFalse(a.ToolAvailable) {
		status = StatusToolUnavailable
	} else if a.TimedOut {
		status = StatusAgentTimeout
	} else if a.HumanInputRequested {
		status = StatusHumanInputRequired
	} else {
		schemaOK := false
		if len(a.Output) == 0 && a.DeclaredStatus == StatusValidOutput && knownTrue(a.OutputSchemaValid) && isSHA256(a.OutputSHA256) {
			schemaOK = true
		} else {
			var schemaViolations []Violation
			schemaOK, schemaViolations = validateEngineeringOutput(a.Output)
			v = append(v, schemaViolations...)
		}
		if !schemaOK || len(a.LimitsExceeded) != 0 || (a.OutputSchemaValid.State == ObservationKnown && !a.OutputSchemaValid.Value) {
			status = StatusInvalidOutput
		}
	}
	if a.DeclaredStatus != "" {
		if !validRunStatus(a.DeclaredStatus) {
			v = append(v, violation("INVALID_RUN_STATUS", "declared_status", "status fora do conjunto fechado"))
		} else if a.DeclaredStatus != status {
			v = append(v, violation("STATUS_EVIDENCE_MISMATCH", "declared_status", "status declarado diverge das observações"))
		}
	}
	return status, sortViolations(v)
}

func EvaluateRetry(cell Cell, attempts []AttemptObservation) RetryDecision {
	var v []Violation
	if len(attempts) != 1 {
		v = append(v, violation("RETRY_ATTEMPT_COUNT", "attempts", "retry exige exatamente uma tentativa original preservada"))
		for i := 1; i < len(attempts); i++ {
			status, _ := ClassifyAttempt(attempts[i])
			if status == StatusAgentTimeout || status == StatusHumanInputRequired || status == StatusInvalidOutput || knownTrue(attempts[i].ModelOutputObserved) {
				v = append(v, violation("RETRY_BEHAVIORAL_FAILURE", fmt.Sprintf("attempts[%d]", i), "falha ou saída comportamental não autoriza repetição"))
			}
		}
		return deniedRetry(v)
	}
	a := attempts[0]
	status, classViolations := ClassifyAttempt(a)
	v = append(v, classViolations...)
	if status != StatusInfraFailure {
		v = append(v, violation("RETRY_BEHAVIORAL_FAILURE", "attempts[0].status", "somente INFRA_FAILURE autoriza retry"))
	}
	if !knownTrue(a.InfrastructureFailureConfirmed) {
		v = append(v, violation("RETRY_INFRA_UNCONFIRMED", "attempts[0].infrastructure_failure_confirmed", "falha de infraestrutura deve ser confirmada"))
	}
	if !knownFalse(a.ModelOutputObserved) {
		v = append(v, violation("RETRY_OUTPUT_NOT_KNOWN_ABSENT", "attempts[0].model_output_observed", "UNKNOWN ou saída observada proíbe retry"))
	}
	if cell.Budget.MaxInfrastructureRetries != 1 {
		v = append(v, violation("RETRY_BUDGET", "cell.budget.max_infrastructure_retries", "budget deve permitir exatamente um retry de infraestrutura"))
	}
	if a.AttemptIndex > 1 || a.PreviousAttemptID != "" {
		v = append(v, violation("RETRY_ALREADY_USED", "attempts[0]", "a tentativa observada já é retry"))
	}
	if a.CellID != "" && a.CellID != cell.CellID || a.ProfileID != "" && a.ProfileID != cell.ProfileID || a.Arm != "" && a.Arm != cell.Arm || a.PromptSHA256 != "" && a.PromptSHA256 != cell.EffectivePromptSHA256 || a.ToolAllowlistSHA256 != "" && a.ToolAllowlistSHA256 != cell.ToolAllowlistSHA256 || !zeroBudget(a.Budget) && !reflect.DeepEqual(a.Budget, cell.Budget) {
		v = append(v, violation("RETRY_IDENTITY_DRIFT", "attempts[0]", "retry deve preservar célula, perfil, braço, hashes e budget"))
	}
	if len(v) != 0 {
		return deniedRetry(v)
	}
	return RetryDecision{Disposition: RetryAllow, Decision: RetryAllow, Allowed: true, Violations: []Violation{}}
}

func BuildRunReceipt(cell Cell, attempts []AttemptObservation) (AgentRunReceipt, []Violation) {
	var v []Violation
	if len(attempts) == 0 || len(attempts) > 2 {
		v = append(v, violation("ATTEMPT_COUNT", "attempts", "receipt exige uma tentativa ou uma tentativa mais um retry"))
	}
	receipt := AgentRunReceipt{
		ExperimentID:         cell.ExperimentID,
		CellID:               cell.CellID,
		PairID:               cell.PairID,
		CaseID:               cell.CaseID,
		ProfileID:            cell.ProfileID,
		Arm:                  cell.Arm,
		PromptSHA256:         cell.EffectivePromptSHA256,
		ToolAllowlistSHA256:  cell.ToolAllowlistSHA256,
		BateiaBuildSHA256:    cell.BateiaBuildSHA256,
		ReplaySnapshotSHA256: cell.ReplaySnapshotSHA256,
		Attempts:             []AttemptReceipt{},
		ToolCalls:            []SafeToolCallReceipt{},
		LimitsExceeded:       []string{},
	}
	for i, a := range attempts {
		status, cv := ClassifyAttempt(a)
		v = append(v, cv...)
		if a.AttemptIndex != i && a.AttemptIndex != i+1 {
			v = append(v, violation("ATTEMPT_INDEX", fmt.Sprintf("attempts[%d].attempt_index", i), "índice de tentativa deve ser sequencial"))
		}
		if i > 0 {
			decision := EvaluateRetry(cell, attempts[:i])
			if !decision.Allowed {
				v = append(v, decision.Violations...)
			}
			if a.PreviousAttemptID != attempts[i-1].AttemptID {
				v = append(v, violation("ATTEMPT_LINK", fmt.Sprintf("attempts[%d].previous_attempt_id", i), "retry deve referenciar a tentativa original"))
			}
		}
		outputHash := a.OutputSHA256
		if len(a.Output) != 0 {
			outputHash = digestBytes(a.Output)
		}
		ar := AttemptReceipt{
			AttemptID:                      a.AttemptID,
			AttemptIndex:                   a.AttemptIndex,
			PreviousAttemptID:              a.PreviousAttemptID,
			StartedAt:                      a.StartedAt,
			FinishedAt:                     a.FinishedAt,
			Status:                         status,
			InfrastructureFailureConfirmed: a.InfrastructureFailureConfirmed,
			ModelOutputObserved:            a.ModelOutputObserved,
			OutputSHA256:                   outputHash,
			OutputSchemaValid:              a.OutputSchemaValid,
			LimitsExceeded:                 append([]string(nil), a.LimitsExceeded...),
			Usage:                          a.Usage,
			ToolCalls:                      append([]SafeToolCallReceipt(nil), a.ToolCalls...),
		}
		receipt.Attempts = append(receipt.Attempts, ar)
		receipt.ToolCalls = append(receipt.ToolCalls, a.ToolCalls...)
		receipt.LimitsExceeded = append(receipt.LimitsExceeded, a.LimitsExceeded...)
		v = append(v, validateUsage(a.Usage, fmt.Sprintf("attempts[%d].usage", i), cell.Budget, cell.Arm)...)
		v = append(v, validateToolCalls(a.ToolCalls, fmt.Sprintf("attempts[%d].tool_calls", i), cell.Arm)...)
	}
	if len(attempts) != 0 {
		first := attempts[0]
		last := attempts[len(attempts)-1]
		receipt.StartedAt = first.StartedAt
		receipt.FinishedAt = last.FinishedAt
		receipt.Status, _ = ClassifyAttempt(last)
		receipt.OutputSchemaValid = last.OutputSchemaValid
		receipt.Usage = aggregateUsage(attempts)
		receipt.OutputSHA256 = last.OutputSHA256
		if len(last.Output) != 0 {
			receipt.OutputSHA256 = digestBytes(last.Output)
		}
	}
	if len(receipt.LimitsExceeded) != 0 {
		sort.Strings(receipt.LimitsExceeded)
	}
	receipt.ReceiptSHA256 = ""
	receipt.ReceiptSHA256, _ = canonicalHash(receipt)
	return receipt, sortViolations(v)
}

func Anonymize(in AnonymizationInput) (JudgingProjection, []Violation) {
	var v []Violation
	original := in.Original
	if original == nil {
		original = in.OriginalOutput
	}
	if original == nil {
		original = in.OriginalJSON
	}
	seed := in.OrderSeed
	if seed == "" {
		seed = in.Seed
	}
	if seed == "" {
		seed = in.OrderingSeed
	}
	policy := in.Policy
	textPolicy := in.TextPolicy
	if textPolicy.SymmetricAcrossArms || textPolicy.Symmetric {
		textPolicy.Frozen = true
		textPolicy.SymmetricAcrossArms = true
	}
	if !policy.Frozen && textPolicy.Frozen {
		policy = textPolicy
	}
	status := in.Status
	if status == "" && len(original) != 0 {
		status = StatusValidOutput
	}
	aliases := map[string]string{}
	for _, source := range []map[string]string{in.GlobalAliases, in.AliasMap, in.Aliases} {
		for key, value := range source {
			if previous, ok := aliases[key]; ok && previous != value {
				v = append(v, violation("ALIAS_INCONSISTENT", "aliases."+key, "mapas globais atribuem aliases diferentes"))
			}
			aliases[key] = value
		}
	}
	for key, value := range in.AliasAssignments {
		if aliases[key] != "" && aliases[key] != value {
			v = append(v, violation("ALIAS_INCONSISTENT", "alias_assignments."+key, "atribuição diverge do mapa global"))
		}
		if aliases[key] == "" {
			aliases[key] = value
		}
	}
	for _, reference := range in.AliasAssignmentConflicts {
		v = append(v, violation("ALIAS_INCONSISTENT", "alias_assignments."+reference, "referência recebeu aliases duplicados divergentes"))
	}
	projection := JudgingProjection{ProjectionID: in.ProjectionID, Status: status, Judgable: status == StatusValidOutput}
	if in.ProjectionID == "" || seed == "" {
		v = append(v, violation("ANONYMIZATION_INPUT", "projection_id", "projection_id e seed são obrigatórios"))
	}
	if original != nil {
		projection.OriginalSHA256 = digestBytes(original)
	}
	if !policy.Frozen || !policy.SymmetricAcrossArms {
		v = append(v, violation("ANONYMIZATION_POLICY", "policy", "política deve estar congelada e ser simétrica entre braços"))
	}
	if policy.ReplaceBateia && policy.NeutralMarker == "" {
		v = append(v, violation("NEUTRAL_MARKER", "policy.neutral_marker", "substituição de Bateia exige marcador neutro congelado"))
	}
	for _, field := range in.JudgeVisibleMetadata {
		lower := strings.ToLower(field)
		if lower == "arm" || strings.Contains(lower, "model") || strings.Contains(lower, "effort") || strings.Contains(lower, "profile") || strings.Contains(lower, "pair") || strings.Contains(lower, "timestamp") {
			v = append(v, violation("JUDGE_IDENTITY_LEAK", "judge_visible_metadata", "metadado revela identidade experimental ao julgador"))
		}
	}
	if in.NormalizeGrammar {
		v = append(v, violation("ANONYMIZER_CONTENT_MUTATION", "normalize_grammar", "anonimização não pode corrigir gramática ou conteúdo"))
	}
	for _, av := range validateAliases(aliases) {
		if av.Code == "ALIAS_COLLISION" {
			av.Code = "ALIAS_INCONSISTENT"
		}
		v = append(v, av)
	}

	if status != StatusValidOutput {
		content, _ := canonicalJSON(map[string]any{"status": status})
		projection.Content = content
		projection.ProjectionSHA256 = digestBytes(content)
		projection.OrderKey = digestParts(seed, in.ProjectionID)
		projection.Judgable = false
		return projection, sortViolations(v)
	}
	if ok, schemaV := validateEngineeringOutput(original); !ok {
		v = append(v, schemaV...)
		projection.Judgable = false
		return projection, sortViolations(v)
	}
	var value any
	decoder := json.NewDecoder(bytes.NewReader(original))
	decoder.UseNumber()
	if err := decoder.Decode(&value); err != nil {
		v = append(v, violation("INVALID_JSON", "original", "JSON não pôde ser decodificado"))
		return projection, sortViolations(v)
	}
	remove := map[string]bool{
		"arm": true, "model_id": true, "resolved_model_id": true, "model": true,
		"reasoning_effort": true, "effort": true, "family_label": true, "profile_id": true,
		"pair_id": true, "started_at": true, "finished_at": true, "timestamp": true,
		"timestamps": true, "execution_metadata": true, "runtime_metadata": true,
	}
	for _, field := range policy.AdditionalMetadataFields {
		remove[field] = true
	}
	value, av := anonymizeValue(value, "", remove, aliases, policy)
	v = append(v, av...)
	content, err := canonicalJSON(value)
	if err != nil {
		v = append(v, violation("CANONICAL_JSON", "content", err.Error()))
		return projection, sortViolations(v)
	}
	projection.Content = content
	projection.ProjectionSHA256 = digestBytes(content)
	projection.OrderKey = digestParts(seed, in.ProjectionID)
	return projection, sortViolations(v)
}

func Score(in ScoringInput) (ScoredRun, []Violation) {
	status := in.Status
	if status == "" && len(in.Ratings) != 0 {
		status = StatusValidOutput
	}
	run := ScoredRun{
		ExperimentID: in.ExperimentID, ProjectionID: in.ProjectionID, PairID: in.PairID,
		CaseID: in.CaseID, ProfileID: in.ProfileID, FamilyLabel: in.FamilyLabel,
		ReasoningEffort: in.ReasoningEffort, Arm: in.Arm, Split: in.Split, Status: status,
		Ratings: append([]JudgeRating(nil), in.Ratings...), Usage: in.Usage,
		CriticalViolations: []CriticalViolation{},
	}
	var v []Violation
	rubricChanged := in.RubricChangedAfterTest || hashesDifferWhenPresent(in.RubricSHA256, in.FrozenRubricSHA256) || hashesDifferWhenPresent(in.RubricBeforeTestSHA256, in.RubricAtScoringSHA256)
	if in.TestOpened && rubricChanged {
		v = append(v, violation("RUBRIC_CHANGED_AFTER_TEST", "rubric", "rubrica não pode mudar após abertura do TEST"))
	}
	criticalPolicy := strings.ToUpper(in.CriticalViolationPolicy)
	if strings.Contains(criticalPolicy, "SCORE") || strings.Contains(criticalPolicy, "HIDE") || strings.Contains(criticalPolicy, "FOLD") || strings.Contains(criticalPolicy, "COMPOSITE") {
		v = append(v, violation("CRITICAL_VIOLATION_HIDDEN", "critical_violation_policy", "violações críticas devem permanecer separadas do score"))
	}
	if len(in.JudgeCriticalViolations) != 0 && len(in.ReportedCriticalViolations) == 0 {
		v = append(v, violation("CRITICAL_VIOLATION_HIDDEN", "reported_critical_violations", "violações críticas julgadas não foram publicadas"))
	}
	switch status {
	case StatusAgentTimeout, StatusHumanInputRequired, StatusInvalidOutput:
		run.Score = Observation[float64]{State: ObservationKnown, Value: 0}
		run.PolicyZero = true
		if len(in.Ratings) != 0 {
			v = append(v, violation("POLICY_ZERO_JUDGED", "ratings", "falha comportamental recebe zero de política, não julgamento"))
		}
		return run, sortViolations(v)
	case StatusToolUnavailable, StatusProfileUnavailable, StatusInfraFailure:
		run.Score = Observation[float64]{State: ObservationUnknown, Reason: "resultado de qualidade não observável por falha não comportamental"}
		if len(in.Ratings) != 0 {
			v = append(v, violation("UNKNOWN_RUN_JUDGED", "ratings", "falha não comportamental não pode receber score"))
		}
		return run, sortViolations(v)
	case StatusValidOutput:
	default:
		run.Score = Observation[float64]{State: ObservationUnknown, Reason: "status inválido"}
		v = append(v, violation("INVALID_RUN_STATUS", "status", "status fora do conjunto fechado"))
		return run, sortViolations(v)
	}

	judgeDimensions := map[string]map[string]bool{}
	judgeExperts := map[string]bool{}
	categoryJudges := map[string]map[string]bool{}
	categoryEvidence := map[string]string{}
	total := 0
	for i, rating := range in.Ratings {
		path := fmt.Sprintf("ratings[%d]", i)
		dimensionID, dimensionOK := normalizeDimensionID(rating.DimensionID)
		if rating.ProjectionID != in.ProjectionID {
			v = append(v, violation("JUDGE_PROJECTION", path+".projection_id", "julgamento pertence a outra projeção"))
		}
		if rating.JudgeID == "" || !dimensionOK {
			v = append(v, violation("JUDGE_IDENTITY", path, "julgador e dimensão devem pertencer à rubrica congelada"))
			continue
		}
		if rating.Rating < 0 || rating.Rating > 4 {
			v = append(v, violation("RATING_RANGE", path+".rating", "nota deve ser inteiro entre 0 e 4"))
			continue
		}
		if judgeDimensions[rating.JudgeID] == nil {
			judgeDimensions[rating.JudgeID] = map[string]bool{}
		}
		if judgeDimensions[rating.JudgeID][dimensionID] {
			v = append(v, violation("DUPLICATE_RATING", path, "julgador repetiu dimensão"))
			continue
		}
		judgeDimensions[rating.JudgeID][dimensionID] = true
		judgeExperts[rating.JudgeID] = judgeExperts[rating.JudgeID] || rating.DomainExpert
		total += rating.Rating
		for _, critical := range rating.CriticalViolations {
			if !criticalCategories[critical.Category] {
				v = append(v, violation("CRITICAL_CATEGORY", path+".critical_violations", "categoria crítica fora da rubrica"))
				continue
			}
			if categoryJudges[critical.Category] == nil {
				categoryJudges[critical.Category] = map[string]bool{}
			}
			categoryJudges[critical.Category][rating.JudgeID] = true
			if categoryEvidence[critical.Category] == "" {
				categoryEvidence[critical.Category] = critical.Evidence
			}
		}
	}
	if len(in.Ratings) != 30 || len(judgeDimensions) != 3 {
		v = append(v, violation("RATING_COUNT", "ratings", "saída válida exige 30 notas de três julgadores"))
	}
	expert := false
	for judge, dimensions := range judgeDimensions {
		if len(dimensions) != 10 {
			v = append(v, violation("JUDGE_DIMENSIONS", "ratings", "julgador "+judge+" deve cobrir dez dimensões"))
		}
		expert = expert || judgeExperts[judge]
	}
	if !expert {
		v = append(v, violation("DOMAIN_EXPERT", "ratings", "ao menos um julgador deve possuir experiência no domínio"))
	}
	for category, judges := range categoryJudges {
		if len(judges) >= 2 {
			run.CriticalViolations = append(run.CriticalViolations, CriticalViolation{Category: category, Evidence: categoryEvidence[category]})
		}
	}
	sort.Slice(run.CriticalViolations, func(i, j int) bool { return run.CriticalViolations[i].Category < run.CriticalViolations[j].Category })
	run.CriticalViolationCount = len(run.CriticalViolations)
	claimedCritical := append([]CriticalViolation(nil), in.JudgeCriticalViolations...)
	claimedCritical = append(claimedCritical, run.CriticalViolations...)
	for _, critical := range claimedCritical {
		if !criticalCategoryPresent(in.ReportedCriticalViolations, critical.Category) {
			v = append(v, violation("CRITICAL_VIOLATION_HIDDEN", "reported_critical_violations", "categoria crítica julgada não foi publicada: "+critical.Category))
		}
	}
	if len(v) == 0 {
		run.Score = Observation[float64]{State: ObservationKnown, Value: 100 * float64(total) / 120}
	} else {
		run.Score = Observation[float64]{State: ObservationUnknown, Reason: "julgamento incompleto ou inválido"}
	}
	return run, sortViolations(v)
}

func Analyze(in AnalysisInput) (ExperimentAnalysis, []Violation) {
	if len(in.Runs) == 0 && len(in.ScoredRuns) != 0 {
		in.Runs = in.ScoredRuns
	}
	analysis := ExperimentAnalysis{
		Pairs: []PairAnalysis{}, FamilyStrata: []StratumAnalysis{}, EffortStrata: []StratumAnalysis{},
		InteractionStrata: []StratumAnalysis{}, ValidByArm: map[Arm]int{}, DispatchedByArm: map[Arm]int{},
		CriticalViolationsByArm: map[Arm]int{}, BehavioralSessions: in.BehavioralSessions, TestReopened: in.TestReopened,
	}
	var v []Violation
	if len(in.DispatchedCellIDs) != 0 && !sameStringSet(in.DispatchedCellIDs, in.IncludedCellIDs) {
		v = append(v, violation("ITT_DENOMINATOR_EXCLUSION", "included_cell_ids", "toda célula despachada deve permanecer no denominador"))
	}
	if len(in.ExcludedProfileIDs) != 0 {
		v = append(v, violation("ITT_DENOMINATOR_EXCLUSION", "excluded_profile_ids", "perfis não podem ser excluídos da intenção de tratar"))
		v = append(v, violation("REGRESSION_DISCARDED", "excluded_profile_ids", "perfil observado não pode ser descartado da análise"))
	}
	if in.AnalysisKind != "" && strings.ToUpper(in.AnalysisKind) != "INTENTION_TO_TREAT" && len(in.DispatchedCellIDs) != 0 {
		v = append(v, violation("ITT_DENOMINATOR_EXCLUSION", "analysis_kind", "análise primária deve seguir intenção de tratar"))
	}
	if strings.Contains(strings.ToUpper(in.QualityMetric), "POPULAR") {
		v = append(v, violation("POPULARITY_USED_AS_QUALITY", "quality_metric", "popularidade não mede qualidade de engenharia"))
	}
	if in.NonSignificant && strings.Contains(strings.ToUpper(in.Interpretation), "EQUIVAL") {
		v = append(v, violation("NON_SIGNIFICANCE_AS_EQUIVALENCE", "interpretation", "não significância não demonstra equivalência"))
	}
	if in.UnknownPromoted {
		v = append(v, violation("UNKNOWN_PROMOTED", "unknown_promoted", "Unknown não pode virar fato, zero ou sucesso"))
	}
	pairIdentity := map[string]ScoredRun{}
	for _, run := range in.Runs {
		if prior, exists := pairIdentity[run.PairID]; exists {
			if prior.CaseID != run.CaseID || prior.ProfileID != run.ProfileID || prior.FamilyLabel != run.FamilyLabel || prior.ReasoningEffort != run.ReasoningEffort {
				v = append(v, violation("PAIR_PROFILE_MISMATCH", "runs["+run.PairID+"]", "par contém caso, perfil ou esforço divergente"))
			}
		} else {
			pairIdentity[run.PairID] = run
		}
	}
	groups := map[string][]ScoredRun{}
	allRatings := []JudgeRating{}
	for _, run := range in.Runs {
		if run.Score.State == ObservationUnknown && run.Score.Value != 0 || run.Score.State == "" && run.Score.Value != 0 {
			v = append(v, violation("UNKNOWN_PROMOTED", "runs["+run.ProjectionID+"].score", "score desconhecido não pode ser promovido a valor"))
		}
		if (run.Status == StatusProfileUnavailable || run.Status == StatusToolUnavailable || run.Status == StatusInfraFailure) && run.Score.State == ObservationKnown {
			v = append(v, violation("UNKNOWN_PROMOTED", "runs["+run.ProjectionID+"].score", "falha não comportamental deve manter score UNKNOWN"))
		}
		if run.Split != SplitTest {
			continue
		}
		groups[run.PairID] = append(groups[run.PairID], run)
		if run.Status == StatusValidOutput {
			analysis.ValidByArm[run.Arm]++
			allRatings = append(allRatings, run.Ratings...)
		}
		analysis.CriticalViolationsByArm[run.Arm] += run.CriticalViolationCount
	}
	if len(in.ObservedStrata) != 0 {
		observed := stringSet(in.ObservedStrata)
		for _, run := range in.Runs {
			familyEffort := run.FamilyLabel + "/" + string(run.ReasoningEffort)
			if !observed[run.FamilyLabel] && !observed[string(run.ReasoningEffort)] && !observed[familyEffort] {
				v = append(v, violation("REGRESSION_DISCARDED", "observed_strata", "estrato observado foi omitido: "+familyEffort))
			}
		}
	}
	for _, cell := range in.DispatchedCells {
		if cell.Split == SplitTest {
			analysis.DispatchedByArm[cell.Arm]++
		}
	}
	pairIDs := make([]string, 0, len(groups))
	for id := range groups {
		pairIDs = append(pairIDs, id)
	}
	sort.Strings(pairIDs)
	for _, id := range pairIDs {
		runs := groups[id]
		pair := PairAnalysis{PairID: id}
		var a, b *ScoredRun
		for i := range runs {
			run := &runs[i]
			if run.Arm == ArmAgentAlone {
				if a != nil {
					v = append(v, violation("DUPLICATE_PAIR_ARM", "pairs["+id+"]", "par contém mais de um braço A"))
				}
				a = run
			} else if run.Arm == ArmAgentWithBateia {
				if b != nil {
					v = append(v, violation("DUPLICATE_PAIR_ARM", "pairs["+id+"]", "par contém mais de um braço B"))
				}
				b = run
			} else {
				v = append(v, violation("INVALID_ARM", "pairs["+id+"]", "braço fora do conjunto fechado"))
			}
		}
		if a == nil || b == nil {
			pair.Uplift = Observation[float64]{State: ObservationUnknown, Reason: "par incompleto"}
			analysis.UnknownPairs++
			v = append(v, violation("INCOMPLETE_PAIR", "pairs["+id+"]", "par deve conter A e B"))
			analysis.Pairs = append(analysis.Pairs, pair)
			continue
		}
		pair.CaseID, pair.ProfileID, pair.FamilyLabel, pair.ReasoningEffort = a.CaseID, a.ProfileID, a.FamilyLabel, a.ReasoningEffort
		pair.ScoreA, pair.ScoreB = a.Score, b.Score
		if a.CaseID != b.CaseID || a.ProfileID != b.ProfileID || a.FamilyLabel != b.FamilyLabel || a.ReasoningEffort != b.ReasoningEffort {
			pair.Uplift = Observation[float64]{State: ObservationUnknown, Reason: "pareamento cruzado"}
			analysis.UnknownPairs++
			v = append(v, violation("PAIR_PROFILE_MISMATCH", "pairs["+id+"]", "uplift só pode comparar mesmo caso, perfil e esforço"))
		} else if a.Score.State != ObservationKnown || b.Score.State != ObservationKnown {
			pair.Uplift = Observation[float64]{State: ObservationUnknown, Reason: "score de um braço é desconhecido"}
			analysis.UnknownPairs++
		} else {
			uplift := b.Score.Value - a.Score.Value
			pair.Uplift = Observation[float64]{State: ObservationKnown, Value: uplift}
			switch {
			case uplift > 0:
				pair.Outcome = "WIN"
				analysis.Wins++
			case uplift < 0:
				pair.Outcome = "LOSS"
				analysis.Losses++
			default:
				pair.Outcome = "TIE"
				analysis.Ties++
			}
		}
		analysis.Pairs = append(analysis.Pairs, pair)
	}
	denominator := len(analysis.Pairs)
	if denominator == 0 {
		analysis.WeightedWinRate = Observation[float64]{State: ObservationUnknown, Reason: "nenhum par TEST"}
	} else {
		analysis.WeightedWinRate = Observation[float64]{State: ObservationKnown, Value: (float64(analysis.Wins) + 0.5*float64(analysis.Ties)) / float64(denominator)}
	}
	analysis.OverallMedianUplift = medianOfPairs(analysis.Pairs)
	analysis.FamilyStrata = buildStrata(analysis.Pairs, func(p PairAnalysis) string { return p.FamilyLabel })
	analysis.EffortStrata = buildStrata(analysis.Pairs, func(p PairAnalysis) string { return string(p.ReasoningEffort) })
	analysis.InteractionStrata = buildStrata(analysis.Pairs, func(p PairAnalysis) string { return p.FamilyLabel + "/" + string(p.ReasoningEffort) })
	analysis.Agreement, v = krippendorffAlpha(allRatings, v)
	if in.BehavioralSessions > 108 {
		v = append(v, violation("BEHAVIORAL_SESSION_CAP", "behavioral_sessions", "teto de 108 sessões comportamentais excedido"))
	}
	if in.TestReopened {
		v = append(v, violation("TEST_REOPENED", "test_reopened", "o split TEST não pode ser repetido"))
	}
	return analysis, sortViolations(v)
}

func EvaluateGates(in GateInput) GateResult {
	var inconclusive []Violation
	var audit []Violation
	check := func(ok bool, code, path, message string) {
		if !ok {
			inconclusive = append(inconclusive, violation(code, path, message))
		}
	}
	check(in.ProfilesAvailableAndExact && in.ExactProfiles == 9, "GATE_PROFILES", "profiles", "nove perfis exatos e disponíveis são obrigatórios")
	check(in.HashesAndDesignSealed, "GATE_SEAL", "sealed", "hashes e desenho devem estar selados")
	check(in.MatrixValid && in.TestCellsDispatched == 54 && in.TestPairs == 27, "GATE_MATRIX", "matrix", "matriz confirmatória deve conter 54 células e 27 pares")
	check(in.NoExposureOrLeakage, "GATE_EXPOSURE", "exposure", "exposição ou vazamento invalida a inferência")
	check(in.InstrumentationComplete, "GATE_INSTRUMENTATION", "instrumentation", "instrumentação incompleta")
	check(in.InfrastructureComplete, "GATE_INFRASTRUCTURE", "infrastructure", "há falha de infraestrutura sem resultado")
	check(in.BudgetsRespected, "GATE_BUDGET", "budgets", "budget de sessão foi violado")
	behavioralSessions := in.BehavioralSessions
	if in.BehavioralSessionCount != 0 {
		behavioralSessions = in.BehavioralSessionCount
	}
	if behavioralSessions == 0 {
		behavioralSessions = in.Analysis.BehavioralSessions
	}
	behavioralLimit := in.BehavioralSessionLimit
	if behavioralLimit == 0 {
		behavioralLimit = 108
	}
	check(behavioralSessions <= behavioralLimit || in.AdditionalBudgetAuthorized, "BEHAVIORAL_SESSION_LIMIT_EXCEEDED", "behavioral_sessions", "teto de sessões comportamentais excedido")
	check(!in.TestReopened && !in.Analysis.TestReopened, "GATE_TEST_REOPENED", "test_reopened", "TEST foi reaberto")
	agreement := in.Agreement
	if agreement.State == "" {
		agreement = in.Analysis.Agreement
	}
	check(agreement.State == ObservationKnown && agreement.Value >= 0.67, "GATE_AGREEMENT", "agreement", "agreement deve ser conhecido e pelo menos 0,67")
	check(in.RefinementsPreserved, "GATE_REFINEMENTS", "refinements", "refinamentos 0025–0028 não foram demonstrados como preservados")
	check(in.MutationScore.State == ObservationKnown && in.MutationScore.Value == 1, "GATE_MUTATION_SCORE", "mutation_score", "mutation score deve ser exatamente 1,0")
	check(in.MutationPositivesPreserved, "GATE_MUTATION_POSITIVES", "mutation_positives", "casos positivos não foram preservados")
	check(in.MutationOpaquesPreserved, "GATE_MUTATION_OPAQUES", "mutation_opaques", "casos opacos não preservaram Unknown")
	check(!in.CalibrationBlockedByNoGain, "GATE_CALIBRATION_YIELD", "calibration", "duas revisões sem ganho exigem redesenho")
	if revisionStopRequired(in.RevisionHistory, in.FullGateRequested) {
		inconclusive = append(inconclusive, violation("REVISION_NO_GAIN_STOP_REQUIRED", "revision_history", "duas revisões da mesma causa sem ganho exigem parada e redesenho"))
	}
	referenceObservation := in.ResolvableBateiaEvidenceFraction
	if referenceObservation.State == "" && in.ReferencesIntegrityRate != 0 {
		referenceObservation = Observation[float64]{State: ObservationKnown, Value: in.ReferencesIntegrityRate}
	}
	if referenceObservation.State != ObservationKnown {
		inconclusive = append(inconclusive, violation("GATE_EVIDENCE_UNKNOWN", "resolvable_bateia_evidence_fraction", "auditoria de referências está incompleta"))
	}
	if in.ProductOnlyPromotions > 0 {
		audit = append(audit, violation("PRODUCT_ONLY_PROMOTED", "product_only_promotions", "artifact product-only foi promovido a arquitetura provada"))
	}
	if in.UnknownToFactConversions > 0 {
		audit = append(audit, violation("UNKNOWN_PROMOTED", "unknown_to_fact_conversions", "Unknown foi promovido a fato"))
	}

	overallMedian := in.Analysis.OverallMedianUplift
	if in.OverallMedianUplift.State != "" {
		overallMedian = in.OverallMedianUplift
	}
	weightedWinRate := in.Analysis.WeightedWinRate
	if in.WeightedWinRate.State != "" {
		weightedWinRate = in.WeightedWinRate
	}
	familyStrata := in.Analysis.FamilyStrata
	if len(in.FamilyMedianUplift) != 0 {
		familyStrata = flattenedStrata(in.FamilyMedianUplift, 9)
	}
	effortStrata := in.Analysis.EffortStrata
	if len(in.EffortMedianUplift) != 0 {
		effortStrata = flattenedStrata(in.EffortMedianUplift, 9)
	}
	materialRegression := in.CriticalViolationsB > in.CriticalViolationsA || (overallMedian.State == ObservationKnown && overallMedian.Value <= -10)
	if len(inconclusive) != 0 {
		return GateResult{Verdict: VerdictInconclusive, Reasons: sortViolations(append(inconclusive, audit...)), MaterialRegression: materialRegression}
	}

	generalBenefit := in.ValidBCells >= 25 && weightedWinRate.State == ObservationKnown && weightedWinRate.Value >= 0.65 && overallMedian.State == ObservationKnown && overallMedian.Value >= 10
	safety := in.CriticalViolationsB <= in.CriticalViolationsA && referenceObservation.Value == 1 && in.ProductOnlyPromotions == 0 && in.UnknownToFactConversions == 0
	familyOK := strataNonNegative(familyStrata, []string{"LUNA", "TERRA", "SOL"}, 9)
	effortOK := strataNonNegative(effortStrata, []string{"low", "medium", "high"}, 9)
	if generalBenefit && safety && familyOK && effortOK {
		return GateResult{Verdict: VerdictUpliftDemonstrated, Reasons: []Violation{}, MaterialRegression: materialRegression}
	}
	if generalBenefit && safety && (!familyOK || !effortOK) {
		return GateResult{Verdict: VerdictPartial, Reasons: []Violation{violation("PROFILE_DEPENDENT_REGRESSION", "strata", "ao menos uma família ou esforço tem mediana negativa")}, MaterialRegression: materialRegression}
	}
	reasons := []Violation{violation("UPLIFT_GATES", "analysis", "um ou mais gates conclusivos de benefício ou segurança não passaram")}
	if in.ProductOnlyPromotions > 0 {
		reasons = append(reasons, violation("PRODUCT_ONLY_PROMOTED", "product_only_promotions", "artifact product-only foi promovido a arquitetura provada"))
	}
	if in.UnknownToFactConversions > 0 {
		reasons = append(reasons, violation("UNKNOWN_PROMOTED", "unknown_to_fact_conversions", "Unknown foi promovido a fato"))
	}
	return GateResult{Verdict: VerdictNotDemonstrated, Reasons: sortViolations(reasons), MaterialRegression: materialRegression}
}

func validateBudget(b SessionBudget, path string, bateiaCalls int) []Violation {
	if b.WallClockSeconds == 900 && b.MaxBateiaCalls == bateiaCalls && b.MaxUnchangedStatusPolls == 12 && b.MaxOutputUTF8Characters == 20000 && b.MaxInfrastructureRetries == 1 {
		return nil
	}
	return []Violation{violation("BUDGET_MISMATCH", path, "budget deve ser 900s, chamadas por braço, 12 polls, 20.000 caracteres e um retry")}
}

func validateEngineeringOutput(raw []byte) (bool, []Violation) {
	if !utf8.Valid(raw) {
		return false, []Violation{violation("INVALID_UTF8", "output", "output deve conter UTF-8 válido")}
	}
	if utf8.RuneCount(raw) > 20000 {
		return false, []Violation{violation("OUTPUT_LIMIT", "output", "output excede 20.000 caracteres Unicode")}
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.UseNumber()
	var object map[string]json.RawMessage
	if err := decoder.Decode(&object); err != nil || object == nil {
		return false, []Violation{violation("INVALID_JSON", "output", "output deve ser um único objeto JSON válido")}
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return false, []Violation{violation("TRAILING_JSON", "output", "output deve conter somente um objeto JSON")}
	}
	types := map[string]string{
		"problem_restatement": "string", "conventional_baseline": "strings", "alternatives": "nested",
		"mechanisms": "nested", "improvement_hypotheses": "nested", "reuse_build_decision": "string",
		"evidence_references": "nested", "counter_evidence": "strings", "risks": "strings",
		"unknowns": "strings", "validation_plan": "nested",
	}
	var v []Violation
	for key := range object {
		if _, ok := types[key]; !ok {
			v = append(v, violation("OUTPUT_ADDITIONAL_PROPERTY", "output."+key, "propriedade adicional não permitida"))
		}
	}
	for key, kind := range types {
		rawValue, ok := object[key]
		if !ok {
			v = append(v, violation("OUTPUT_REQUIRED_FIELD", "output."+key, "campo obrigatório ausente"))
			continue
		}
		valid := false
		switch kind {
		case "string":
			var value string
			valid = json.Unmarshal(rawValue, &value) == nil
		case "strings":
			var value []string
			valid = json.Unmarshal(rawValue, &value) == nil && value != nil
		case "nested":
			var nestedViolations []Violation
			valid, nestedViolations = validateClosedObjectArray(rawValue, "output."+key, nestedOutputSchemas[key])
			v = append(v, nestedViolations...)
		}
		if !valid {
			v = append(v, violation("OUTPUT_FIELD_TYPE", "output."+key, "tipo do campo diverge do schema congelado"))
		}
	}
	return len(v) == 0, sortViolations(v)
}

type outputFieldRule struct {
	kind string
	enum map[string]bool
}

var nestedOutputSchemas = map[string]map[string]outputFieldRule{
	"alternatives": {
		"name": {kind: "string"}, "decision": {kind: "string", enum: enumSet("REUSE", "ADAPT", "INVESTIGATE", "BUILD", "UNKNOWN")},
		"fit": {kind: "string"}, "gaps": {kind: "strings"}, "evidence_refs": {kind: "strings"},
	},
	"mechanisms": {
		"name": {kind: "string"}, "operation": {kind: "string"}, "contribution": {kind: "string"},
		"limitations": {kind: "strings"}, "evidence_refs": {kind: "strings"},
	},
	"improvement_hypotheses": {
		"hypothesis": {kind: "string"}, "expected_effect": {kind: "string"}, "assumptions": {kind: "strings"},
		"counterevidence_to_seek": {kind: "strings"}, "evidence_refs": {kind: "strings"},
	},
	"evidence_references": {
		"reference_id": {kind: "string"}, "source_type": {kind: "string", enum: enumSet("BATEIA_RUN", "BATEIA_ARTIFACT", "CASE_INPUT", "PUBLIC_CLAIM", "UNKNOWN")},
		"locator": {kind: "string"}, "sha256": {kind: "string"}, "supports": {kind: "strings"},
		"verification_status": {kind: "string", enum: enumSet("VERIFIED", "UNVERIFIED", "UNKNOWN")},
	},
	"validation_plan": {
		"target": {kind: "string"}, "method": {kind: "string"}, "success_criterion": {kind: "string"},
		"failure_criterion": {kind: "string"}, "dependencies": {kind: "strings"},
	},
}

func validateClosedObjectArray(raw json.RawMessage, path string, schema map[string]outputFieldRule) (bool, []Violation) {
	var items []json.RawMessage
	if json.Unmarshal(raw, &items) != nil || items == nil {
		return false, nil
	}
	var violations []Violation
	for index, item := range items {
		itemPath := fmt.Sprintf("%s[%d]", path, index)
		var object map[string]json.RawMessage
		if json.Unmarshal(item, &object) != nil || object == nil {
			violations = append(violations, violation("OUTPUT_FIELD_TYPE", itemPath, "item deve ser objeto não nulo"))
			continue
		}
		for key := range object {
			if _, allowed := schema[key]; !allowed {
				violations = append(violations, violation("OUTPUT_ADDITIONAL_PROPERTY", itemPath+"."+key, "propriedade adicional não permitida"))
			}
		}
		for key, rule := range schema {
			value, present := object[key]
			fieldPath := itemPath + "." + key
			if !present {
				violations = append(violations, violation("OUTPUT_REQUIRED_FIELD", fieldPath, "campo obrigatório ausente"))
				continue
			}
			if rule.kind == "string" {
				var decoded string
				if json.Unmarshal(value, &decoded) != nil {
					violations = append(violations, violation("OUTPUT_FIELD_TYPE", fieldPath, "tipo do campo diverge do schema congelado"))
				} else if rule.enum != nil && !rule.enum[decoded] {
					violations = append(violations, violation("OUTPUT_FIELD_ENUM", fieldPath, "valor fora do enum congelado"))
				}
				continue
			}
			var decoded []string
			if json.Unmarshal(value, &decoded) != nil || decoded == nil {
				violations = append(violations, violation("OUTPUT_FIELD_TYPE", fieldPath, "tipo do campo diverge do schema congelado"))
			}
		}
	}
	return len(violations) == 0, violations
}

func enumSet(values ...string) map[string]bool {
	result := make(map[string]bool, len(values))
	for _, value := range values {
		result[value] = true
	}
	return result
}

func validateUsage(usage AgentUsage, path string, budget SessionBudget, arm Arm) []Violation {
	var v []Violation
	for name, observation := range map[string]Observation[int64]{
		"input_tokens": usage.InputTokens, "output_tokens": usage.OutputTokens,
		"reasoning_tokens": usage.ReasoningTokens, "duration_milliseconds": usage.DurationMilliseconds,
		"bateia_calls": usage.BateiaCalls, "unchanged_status_polls": usage.UnchangedStatusPolls,
		"infrastructure_retries": usage.InfrastructureRetries,
	} {
		v = append(v, validateIntObservation(observation, path+"."+name)...)
	}
	if usage.BateiaCalls.State == ObservationKnown {
		maxCalls := int64(budget.MaxBateiaCalls)
		if arm == ArmAgentAlone {
			maxCalls = 0
		}
		if usage.BateiaCalls.Value > maxCalls {
			v = append(v, violation("BATEIA_CALL_BUDGET", path+".bateia_calls", "chamadas excedem o budget do braço"))
		}
	}
	if usage.UnchangedStatusPolls.State == ObservationKnown && usage.UnchangedStatusPolls.Value > int64(budget.MaxUnchangedStatusPolls) {
		v = append(v, violation("POLL_BUDGET", path+".unchanged_status_polls", "polls sem mudança excedem budget"))
	}
	if usage.DurationMilliseconds.State == ObservationKnown && usage.DurationMilliseconds.Value > int64(budget.WallClockSeconds)*1000 {
		v = append(v, violation("TIME_BUDGET", path+".duration_milliseconds", "duração excede budget"))
	}
	if usage.MonetaryCost.State == ObservationKnown {
		if usage.MonetaryCost.Value < 0 || usage.Currency == "" || usage.PriceTableVersion == "" || !isSHA256(usage.PriceTableSHA256) {
			v = append(v, violation("PRICE_PROVENANCE", path+".monetary_cost", "custo exige moeda e tabela congelada versionada"))
		}
	} else {
		v = append(v, validateFloatObservation(usage.MonetaryCost, path+".monetary_cost")...)
	}
	return v
}

func validateToolCalls(calls []SafeToolCallReceipt, path string, arm Arm) []Violation {
	var v []Violation
	for i, call := range calls {
		p := fmt.Sprintf("%s[%d]", path, i)
		if call.Sequence != i && call.Sequence != i+1 {
			v = append(v, violation("TOOL_SEQUENCE", p+".sequence", "sequência de tools deve ser estável"))
		}
		if arm == ArmAgentAlone || !contains(certifiedBateiaTools, call.Name) {
			v = append(v, violation("TOOL_NOT_ALLOWED", p+".name", "tool não pertence à allowlist do braço"))
		}
		if !isSHA256(call.RequestSHA256) || !isSHA256(call.ResponseSHA256) {
			v = append(v, violation("TOOL_BODY_HASH", p, "request e response devem aparecer somente por hashes válidos"))
		}
	}
	return v
}

func aggregateUsage(attempts []AttemptObservation) AgentUsage {
	ints := func(selectValue func(AgentUsage) Observation[int64]) Observation[int64] {
		var sum int64
		for _, attempt := range attempts {
			observation := selectValue(attempt.Usage)
			if observation.State != ObservationKnown {
				return Observation[int64]{State: ObservationUnknown, Reason: "métrica não exposta em todas as tentativas"}
			}
			sum += observation.Value
		}
		return Observation[int64]{State: ObservationKnown, Value: sum}
	}
	retries := len(attempts) - 1
	if retries < 0 {
		retries = 0
	}
	return AgentUsage{
		InputTokens:           ints(func(u AgentUsage) Observation[int64] { return u.InputTokens }),
		OutputTokens:          ints(func(u AgentUsage) Observation[int64] { return u.OutputTokens }),
		ReasoningTokens:       ints(func(u AgentUsage) Observation[int64] { return u.ReasoningTokens }),
		DurationMilliseconds:  ints(func(u AgentUsage) Observation[int64] { return u.DurationMilliseconds }),
		BateiaCalls:           ints(func(u AgentUsage) Observation[int64] { return u.BateiaCalls }),
		UnchangedStatusPolls:  ints(func(u AgentUsage) Observation[int64] { return u.UnchangedStatusPolls }),
		InfrastructureRetries: Observation[int64]{State: ObservationKnown, Value: int64(retries)},
		MonetaryCost:          Observation[float64]{State: ObservationUnknown, Reason: "custo agregado requer tabela congelada comum"},
	}
}

func anonymizeValue(value any, key string, remove map[string]bool, aliases map[string]string, policy AnonymizationPolicy) (any, []Violation) {
	var v []Violation
	switch typed := value.(type) {
	case map[string]any:
		out := make(map[string]any, len(typed))
		for childKey, childValue := range typed {
			if remove[strings.ToLower(childKey)] {
				continue
			}
			anonymized, cv := anonymizeValue(childValue, childKey, remove, aliases, policy)
			v = append(v, cv...)
			out[childKey] = anonymized
		}
		return out, v
	case []any:
		out := make([]any, len(typed))
		for i, child := range typed {
			var cv []Violation
			out[i], cv = anonymizeValue(child, key, remove, aliases, policy)
			v = append(v, cv...)
		}
		return out, v
	case string:
		lowerKey := strings.ToLower(key)
		sensitiveReference := strings.Contains(lowerKey, "run_id") || strings.Contains(lowerKey, "artifact") || strings.Contains(lowerKey, "hash") || strings.Contains(lowerKey, "sha256")
		result := typed
		if sensitiveReference && typed != "" {
			if alias, ok := aliases[typed]; ok {
				result = alias
			} else {
				v = append(v, violation("ALIAS_INCONSISTENT", key, "referência identificável não possui alias global"))
			}
		}
		keys := make([]string, 0, len(aliases))
		for source := range aliases {
			keys = append(keys, source)
		}
		sort.Slice(keys, func(i, j int) bool { return len(keys[i]) > len(keys[j]) })
		for _, source := range keys {
			result = strings.ReplaceAll(result, source, aliases[source])
		}
		if policy.ReplaceBateia {
			result = replaceCaseInsensitive(result, "Bateia", policy.NeutralMarker)
		}
		return result, v
	default:
		return value, nil
	}
}

func validateAliases(aliases map[string]string) []Violation {
	var v []Violation
	seen := map[string]string{}
	for source, alias := range aliases {
		if source == "" || alias == "" {
			v = append(v, violation("ALIAS_EMPTY", "aliases", "origem e alias devem ser não vazios"))
		}
		if previous, exists := seen[alias]; exists && previous != source {
			v = append(v, violation("ALIAS_COLLISION", "aliases", "duas referências usam o mesmo alias"))
		}
		seen[alias] = source
	}
	return v
}

func medianOfPairs(pairs []PairAnalysis) Observation[float64] {
	values := make([]float64, 0, len(pairs))
	for _, pair := range pairs {
		if pair.Uplift.State != ObservationKnown {
			return Observation[float64]{State: ObservationUnknown, Reason: "ao menos um uplift é desconhecido"}
		}
		values = append(values, pair.Uplift.Value)
	}
	return median(values)
}

func buildStrata(pairs []PairAnalysis, key func(PairAnalysis) string) []StratumAnalysis {
	groups := map[string][]PairAnalysis{}
	for _, pair := range pairs {
		groups[key(pair)] = append(groups[key(pair)], pair)
	}
	keys := make([]string, 0, len(groups))
	for k := range groups {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	result := make([]StratumAnalysis, 0, len(keys))
	for _, k := range keys {
		stratum := StratumAnalysis{Key: k, PairCount: len(groups[k]), MedianUplift: medianOfPairs(groups[k])}
		for _, pair := range groups[k] {
			if pair.Uplift.State == ObservationKnown {
				stratum.KnownPairs++
			}
		}
		result = append(result, stratum)
	}
	return result
}

func krippendorffAlpha(ratings []JudgeRating, v []Violation) (Observation[float64], []Violation) {
	units := map[string][]float64{}
	for _, rating := range ratings {
		dimensionID, dimensionOK := normalizeDimensionID(rating.DimensionID)
		if rating.JudgeID == "" || rating.ProjectionID == "" || !dimensionOK || rating.Rating < 0 || rating.Rating > 4 {
			continue
		}
		unit := rating.ProjectionID + "\x00" + dimensionID
		units[unit] = append(units[unit], float64(rating.Rating))
	}
	if len(units) == 0 {
		return Observation[float64]{State: ObservationUnknown, Reason: "não há julgamentos reproduzíveis"}, v
	}
	all := []float64{}
	var observedSum float64
	var observedPairs int
	for unit, values := range units {
		if len(values) != 3 {
			v = append(v, violation("AGREEMENT_MISSING_RATING", "agreement."+unit, "cada unidade exige três notas"))
			return Observation[float64]{State: ObservationUnknown, Reason: "julgamento ausente"}, v
		}
		all = append(all, values...)
		for i := 0; i < len(values); i++ {
			for j := i + 1; j < len(values); j++ {
				d := values[i] - values[j]
				observedSum += d * d
				observedPairs++
			}
		}
	}
	if len(all) < 2 || observedPairs == 0 {
		return Observation[float64]{State: ObservationUnknown, Reason: "amostra insuficiente"}, v
	}
	var expectedSum float64
	var expectedPairs int
	for i := 0; i < len(all); i++ {
		for j := i + 1; j < len(all); j++ {
			d := all[i] - all[j]
			expectedSum += d * d
			expectedPairs++
		}
	}
	de := expectedSum / float64(expectedPairs)
	if de == 0 {
		return Observation[float64]{State: ObservationKnown, Value: 1}, v
	}
	do := observedSum / float64(observedPairs)
	return Observation[float64]{State: ObservationKnown, Value: 1 - do/de}, v
}

func strataNonNegative(strata []StratumAnalysis, required []string, pairCount int) bool {
	byKey := map[string]StratumAnalysis{}
	for _, stratum := range strata {
		byKey[stratum.Key] = stratum
	}
	for _, key := range required {
		stratum, ok := byKey[key]
		if !ok || stratum.PairCount != pairCount || stratum.MedianUplift.State != ObservationKnown || stratum.MedianUplift.Value < 0 {
			return false
		}
	}
	return true
}

func validateBoolObservation(o Observation[bool], path string, required bool) []Violation {
	if o.State == "" && !required {
		return nil
	}
	if o.State != ObservationKnown && o.State != ObservationUnknown && o.State != ObservationNotApplicable {
		return []Violation{violation("OBSERVATION_STATE", path+".state", "estado fora do conjunto fechado")}
	}
	if o.State == ObservationUnknown && strings.TrimSpace(o.Reason) == "" {
		return []Violation{violation("UNKNOWN_REASON", path+".reason", "UNKNOWN exige motivo")}
	}
	return nil
}

func validateIntObservation(o Observation[int64], path string) []Violation {
	if o.State == "" {
		return []Violation{violation("USAGE_OBSERVATION_OMITTED", path, "usage deve registrar KNOWN, UNKNOWN ou NOT_APPLICABLE")}
	}
	if o.State != ObservationKnown && o.State != ObservationUnknown && o.State != ObservationNotApplicable {
		return []Violation{violation("OBSERVATION_STATE", path+".state", "estado fora do conjunto fechado")}
	}
	if o.State == ObservationUnknown && strings.TrimSpace(o.Reason) == "" {
		return []Violation{violation("UNKNOWN_REASON", path+".reason", "UNKNOWN exige motivo")}
	}
	if o.State == ObservationKnown && o.Value < 0 {
		return []Violation{violation("NEGATIVE_USAGE", path+".value", "métrica de uso não pode ser negativa")}
	}
	return nil
}

func validateFloatObservation(o Observation[float64], path string) []Violation {
	if o.State != ObservationKnown && o.State != ObservationUnknown && o.State != ObservationNotApplicable {
		return []Violation{violation("OBSERVATION_STATE", path+".state", "estado fora do conjunto fechado")}
	}
	if o.State == ObservationUnknown && strings.TrimSpace(o.Reason) == "" {
		return []Violation{violation("UNKNOWN_REASON", path+".reason", "UNKNOWN exige motivo")}
	}
	if o.State == ObservationKnown && (math.IsNaN(o.Value) || math.IsInf(o.Value, 0)) {
		return []Violation{violation("NONFINITE_OBSERVATION", path+".value", "observação deve ser finita")}
	}
	return nil
}

func validRunStatus(status RunStatus) bool {
	return status == StatusValidOutput || status == StatusAgentTimeout || status == StatusHumanInputRequired || status == StatusInvalidOutput || status == StatusToolUnavailable || status == StatusProfileUnavailable || status == StatusInfraFailure
}

func knownTrue(o Observation[bool]) bool  { return o.State == ObservationKnown && o.Value }
func knownFalse(o Observation[bool]) bool { return o.State == ObservationKnown && !o.Value }

func zeroBudget(b SessionBudget) bool { return b == (SessionBudget{}) }

func deniedRetry(v []Violation) RetryDecision {
	return RetryDecision{Disposition: RetryDeny, Decision: RetryDeny, Allowed: false, Violations: sortViolations(v)}
}

func median(values []float64) Observation[float64] {
	if len(values) == 0 {
		return Observation[float64]{State: ObservationUnknown, Reason: "nenhum valor observado"}
	}
	sorted := append([]float64(nil), values...)
	sort.Float64s(sorted)
	middle := len(sorted) / 2
	if len(sorted)%2 == 1 {
		return Observation[float64]{State: ObservationKnown, Value: sorted[middle]}
	}
	return Observation[float64]{State: ObservationKnown, Value: (sorted[middle-1] + sorted[middle]) / 2}
}

func digestParts(parts ...string) string {
	h := sha256.New()
	for i, part := range parts {
		if i > 0 {
			h.Write([]byte{0})
		}
		h.Write([]byte(part))
	}
	return hex.EncodeToString(h.Sum(nil))
}

func digestBytes(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func canonicalJSON(value any) ([]byte, error) {
	var buffer bytes.Buffer
	encoder := json.NewEncoder(&buffer)
	encoder.SetEscapeHTML(false)
	encoder.SetIndent("", "")
	if err := encoder.Encode(value); err != nil {
		return nil, err
	}
	return bytes.TrimSuffix(buffer.Bytes(), []byte("\n")), nil
}

func canonicalHash(value any) (string, error) {
	data, err := canonicalJSON(value)
	if err != nil {
		return "", err
	}
	return digestBytes(data), nil
}

func isSHA256(value string) bool {
	if len(value) != 64 {
		return false
	}
	_, err := hex.DecodeString(value)
	return err == nil
}

func contains[T comparable](values []T, value T) bool {
	for _, candidate := range values {
		if candidate == value {
			return true
		}
	}
	return false
}

func hashesDifferWhenPresent(a, b string) bool {
	return a != "" && b != "" && a != b
}

func normalizeDimensionID(value string) (string, bool) {
	for _, dimension := range rubricDimensions {
		if value == dimension || value == dimension[:3] {
			return dimension, true
		}
	}
	return "", false
}

func sameStringSet(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	aSet, bSet := stringSet(a), stringSet(b)
	if len(aSet) != len(bSet) {
		return false
	}
	for value := range aSet {
		if !bSet[value] {
			return false
		}
	}
	return true
}

func stringSet(values []string) map[string]bool {
	result := make(map[string]bool, len(values))
	for _, value := range values {
		result[value] = true
	}
	return result
}

func revisionStopRequired(history []RevisionRecord, fullGateRequested bool) bool {
	if len(history) < 2 {
		return false
	}
	a, b := history[len(history)-2], history[len(history)-1]
	sameCause := a.FailureClass != "" && a.FailureClass == b.FailureClass
	noGain := a.DiscriminatoryDelta <= 0 && b.DiscriminatoryDelta <= 0
	return sameCause && noGain && (fullGateRequested || b.FullGate || b.FullMatrixExecuted)
}

func flattenedStrata(values map[string]float64, pairCount int) []StratumAnalysis {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	result := make([]StratumAnalysis, 0, len(keys))
	for _, key := range keys {
		result = append(result, StratumAnalysis{Key: key, PairCount: pairCount, KnownPairs: pairCount, MedianUplift: Observation[float64]{State: ObservationKnown, Value: values[key]}})
	}
	return result
}

func criticalCategoryPresent(values []CriticalViolation, category string) bool {
	for _, value := range values {
		if value.Category == category {
			return true
		}
	}
	return false
}

func replaceCaseInsensitive(value, target, replacement string) string {
	if target == "" {
		return value
	}
	lowerValue, lowerTarget := strings.ToLower(value), strings.ToLower(target)
	var result strings.Builder
	for {
		index := strings.Index(lowerValue, lowerTarget)
		if index < 0 {
			result.WriteString(value)
			return result.String()
		}
		result.WriteString(value[:index])
		result.WriteString(replacement)
		value = value[index+len(target):]
		lowerValue = lowerValue[index+len(target):]
	}
}

func violation(code, path, message string) Violation {
	return Violation{Code: code, Path: path, Message: message}
}

func sortViolations(v []Violation) []Violation {
	if len(v) == 0 {
		return nil
	}
	out := append([]Violation(nil), v...)
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].Code != out[j].Code {
			return out[i].Code < out[j].Code
		}
		if out[i].Path != out[j].Path {
			return out[i].Path < out[j].Path
		}
		return out[i].Message < out[j].Message
	})
	return out
}

