			}
			candidate := alternativeM17Candidate(t, rankAlternativeTestInput(t, input))
			matrix := map[string]alternativeCapabilityJSON{}
			for _, capability := range candidate.Capabilities {
				matrix[capability.Capability] = capability
			}
